extends Resource
class_name TetrominoData

@export var cells: Array[Vector2i]
@export var atlas_coords: Vector2i

func is_valid_move(piece_cells: Array[Vector2i], offset: Vector2i) -> bool:
	for cell in piece_cells:
		var new_pos = cell + offset
		# 1. Проверка границ поля
		if new_pos.x < 0 or new_pos.x >= 10 or new_pos.y >= 20:
			return false
		# 2. Проверка столкновения с уже лежащими блоками
		if tile_map.get_cell_source_id(new_pos) != -1:
			return false
	return true

