extends Node

signal game_started

@rpc('authority', 'call_local')
func start_game():
	game_started.emit()
	print('БИТВА НАЧАЛАСЬ!')

func _on_start_button_pressed():
	if multiplayer.is_server():
		start_game.rpc() # Запускаем тетрис у всех одновременно

@rpc('any_peer', 'unreliable')
func sync_opponent_data(score: int, lines: int):
	# Обновляем маленькое превью-окошко соперника
	OpponentUI.update_info(score, lines)

func _on_lines_cleared(count):
	sync_opponent_data.rpc(total_score, total_lines)

@rpc('any_peer', 'call_remote')
func receive_garbage(count: int):
	# Сдвигаем всё поле игрока вверх на 'count' линий
	# И снизу добавляем линии с одной случайной дыркой
	for i in range(count):
		grid.add_garbage_row()

@rpc('any_peer', 'call_local')
func player_lost(id: int):
	print('Игрок ', id, ' выбыл из битвы!')
	check_winner()
